from pathlib import Path

p = Path('index.html')
s = p.read_text(encoding='utf-8')

s = s.replace('>🌱 Lavouras</button>', '>🌱 Áreas</button>')

marker = '/* AREAS_MENU_EDIT_V1 */'
if marker not in s:
    patch = '''\n<script>\n/* AREAS_MENU_EDIT_V1 */\nlet areaEditId='';\nfunction cancelarEdicaoArea(){\n  areaEditId='';\n  const f=document.getElementById('fLav'); if(f)f.reset();\n  const b=document.getElementById('areaCancelar'); if(b)b.style.display='none';\n  const sv=document.getElementById('areaSalvar'); if(sv)sv.textContent='Salvar';\n}\nfunction editarArea(id){\n  const a=(db.lavouras||[]).find(x=>String(x.id)===String(id)); if(!a)return;\n  areaEditId=a.id;\n  $('lavCodigo').value=a.codigo||'';\n  $('lavNome').value=a.nome||'';\n  $('lavArea').value=a.area||'';\n  const b=document.getElementById('areaCancelar'); if(b)b.style.display='inline-block';\n  const sv=document.getElementById('areaSalvar'); if(sv)sv.textContent='Salvar alteração';\n  $('lavCodigo').focus();\n}\nfunction excluirArea(id){\n  const a=(db.lavouras||[]).find(x=>String(x.id)===String(id)); if(!a)return;\n  const usada=(db.safras||[]).some(x=>String(x.lavouraId)===String(id)) || (db.aplicacoes||[]).some(x=>String(x.lavouraId)===String(id)) || (db.manejos||[]).some(x=>String(x.lavouraId)===String(id));\n  if(usada)return alert('Esta área possui variedade ou manejo registrado e não pode ser excluída.');\n  if(!confirm('Excluir a área '+(a.nome||a.codigo)+'?'))return;\n  db.lavouras=db.lavouras.filter(x=>String(x.id)!==String(id));\n  save(); cancelarEdicaoArea(); renderAreasTabela();\n}\nfunction renderAreasTabela(){\n  const total=(db.lavouras||[]).reduce((s,a)=>s+n(a.area),0);\n  $('totalLav').innerHTML='<b>ÁREA TOTAL CADASTRADA: '+total.toLocaleString('pt-BR',{maximumFractionDigits:2})+' ha</b>';\n  $('tblLav').innerHTML='<table><tr><th>Código</th><th>Área</th><th>Tamanho</th><th>Ações</th></tr>'+\n    (db.lavouras||[]).map(a=>'<tr><td>'+esc(a.codigo||'')+'</td><td><b>'+esc(a.nome||'')+'</b></td><td>'+n(a.area).toLocaleString('pt-BR',{maximumFractionDigits:2})+' ha</td><td><button class="btn" type="button" onclick="editarArea(\\''+a.id+'\\')">Editar</button> <button class="btn danger" type="button" onclick="excluirArea(\\''+a.id+'\\')">Excluir</button></td></tr>').join('')+'</table>';\n}\n(function(){\n  const f=document.getElementById('fLav'); if(!f)return;\n  const actions=f.querySelector('.actions');\n  if(actions)actions.innerHTML='<button type="button" id="areaCancelar" class="btn" style="display:none" onclick="cancelarEdicaoArea()">Cancelar</button><button id="areaSalvar" class="btn pri">Salvar</button>';\n  f.onsubmit=function(e){\n    e.preventDefault();\n    const codigo=$('lavCodigo').value.trim(), nome=$('lavNome').value.trim(), area=n($('lavArea').value);\n    if(!codigo||!nome||area<=0)return alert('Preencha código, nome e área.');\n    const duplicada=(db.lavouras||[]).some(x=>String(x.id)!==String(areaEditId)&&String(x.codigo||'').toLowerCase()===codigo.toLowerCase());\n    if(duplicada)return alert('Já existe uma área com este código.');\n    if(areaEditId){\n      const a=db.lavouras.find(x=>String(x.id)===String(areaEditId)); if(a){a.codigo=codigo;a.nome=nome;a.area=area;}\n    }else db.lavouras.push({id:uid(),codigo,nome,area});\n    save(); cancelarEdicaoArea(); renderAreasTabela();\n  };\n  const renderOriginal=render;\n  render=function(){renderOriginal();renderAreasTabela();};\n  renderAreasTabela();\n})();\n</script>\n'''
    s = s.replace('</body>', patch + '</body>', 1)

p.write_text(s, encoding='utf-8')
